/** What the apps render: `removed` covers a taken-down photo; a flagged or approved check is `approved`. */
export const MODERATION_STATES = ["pending", "review", "approved", "removed"] as const;
export type ModerationStateStatus = (typeof MODERATION_STATES)[number];

export const moderationStateSchema = z.object({
  status: z.enum(MODERATION_STATES),
  reasonCode: z.string().optional(),
  /** one plain sentence telling the member what to do (removed only) */
  message: z.string().optional(),
});
