/** The check rows' statuses (SPEC 13a §3.13, plus `flagged`). */
export const CHECK_STATUSES = ["pending", "approved", "rejected", "review", "flagged"] as const;
export type CheckStatus = (typeof CHECK_STATUSES)[number];

/** A check row's status as the member sees it. */
export function memberState(status: CheckStatus, reasonCode?: string | null, message?: string | null): ModerationState {
  switch (status) {
    case "pending":
      return { status: "pending" };
    case "review":
      return { status: "review" };
    case "rejected":
      return { status: "removed", ...(reasonCode ? { reasonCode } : {}), ...(message ? { message } : {}) };
    default:
      return { status: "approved" };
  }
}

/** Held: not public until Ops decides (a removed photo is gone anyway; a hidden text is not live). */
export const isHeldStatus = (status: CheckStatus): boolean => status === "review" || status === "rejected";

