/** The message for a reason code of a check kind, or undefined. */
export function reasonMessage(kind: string, reasonCode: string | null | undefined): string | undefined {
  if (!reasonCode) return undefined;
  const code = reasonCode.includes(".") ? reasonCode.slice(reasonCode.indexOf(".") + 1) : reasonCode;
  const table: Record<string, string> =
    kind === CHECK_KINDS.avatar ? REASON_MESSAGES.avatar : kind === CHECK_KINDS.paymentQr ? REASON_MESSAGES.qr : kind.startsWith("image.") ? REASON_MESSAGES.photo : REASON_MESSAGES.text;
  return table[code];
}

// ---- the at-save rule (SPEC 13d §4.3: a sure find is refused with the field message, nothing is stored) ----

const CONTACT_NAMES: Record<ContactKind, string> = {
  email: "the email address",
  url: "the link",
  phone: "the phone number",
  handle: "the social media handle",
  payment_number: "the account number",
  app_invite: "the invitation to another app",
};

/**
 * The field error for a text with a sure contact detail, e.g. "Remove the phone number: clients reach you through
 * Phriend chat.", or null. Weak finds are not refused here (the autopilot sends them to Ops). `[removed]` marks the
 * autopilot left are not contact details.
 */
export function contactFieldProblem(text: string | null | undefined): string | null {
  if (!text) return null;
  const sure = findContacts(text.split(CONTACT_MARK).join(" ")).find((h) => h.sure);
  return sure ? `Remove ${CONTACT_NAMES[sure.kind]}: clients reach you through Phriend chat.` : null;
}

